export function parseMacModelFromRenderer(
	renderer: string
): { type: MacDeviceType; chip: string } | null {
	if (renderer.toLowerCase().includes('or similar')) {
		return null;
	}

	if (/^Apple\s*GPU$/i.test(renderer)) {
		return null;
	}

	const m = renderer.match(/Apple\s+(M\d+(?:\s+(?:Max|Ultra|Pro))?)/i);

	if (!m) {
		return null;
	}

	const chip = m[1].trim();
	const isMaxOrUltra = chip.includes('Max') || chip.includes('Ultra');

	return { chip: `Apple ${chip}`, type: isMaxOrUltra ? 'desktop' : 'macbook' };
}

export function getMacModelFromHeuristics(
	deviceMemory: number | undefined,
	hardwareConcurrency: number | undefined
): MacDeviceType | null {
	if (!deviceMemory || !hardwareConcurrency) {
		return null;
	}

	if (hardwareConcurrency >= 24 && deviceMemory >= 100) {
		return 'desktop';
	}

	if (hardwareConcurrency >= 32 && deviceMemory >= 150) {
		return 'desktop';
	}

	if (hardwareConcurrency <= 16 && deviceMemory >= 8) {
		return 'macbook';
	}

	if (hardwareConcurrency <= 10 && deviceMemory >= 4) {
		return 'macbook';
	}

	return null;
}

import { redirect } from '@sveltejs/kit';

// The index lives at an explicit /docs/introduction URL so that relative links
// between markdown pages resolve correctly.
export const load = () => {
	redirect(307, '/docs/introduction');
};

// Talking to the user's Llama server (the local menu bar app by default, or
// any self-hosted llama-server) from the docs pages.
//
// Detection is ADVISORY ONLY — a failed probe never hard-blocks navigation,
// because it is ambiguous: the server may be down, on another port, or the
// browser may have blocked the request (e.g. Chrome 142+ gates local
// requests behind the Local Network Access permission).
// See https://github.com/ggml-org/llama.pages/pull/30#discussion_r3551723116

import { STORAGE_KEY } from '$lib/constants';

export const DEFAULT_LLAMA_SERVER_URL = 'http://localhost:9931';

export function getLlamaServerUrl(): string {
	return localStorage.getItem(STORAGE_KEY) ?? DEFAULT_LLAMA_SERVER_URL;
}

export function saveLlamaServerUrl(base: string): void {
	localStorage.setItem(STORAGE_KEY, base);
}

/**
 * Accepts a bare port ("9931") or a URL ("llama.example.com",
 * "https://llama.example.com"); returns a normalized base URL, or null.
 */
export function parseLlamaServerInput(input: string): string | null {
	const trimmed = input.trim().replace(/\/+$/, '');

	if (!trimmed) {
		return null;
	}

	if (/^\d+$/.test(trimmed)) {
		const port = Number(trimmed);

		return port >= 1 && port <= 65535 ? `http://localhost:${port}` : null;
	}

	const withProtocol = /^https?:\/\//.test(trimmed) ? trimmed : `https://${trimmed}`;

	try {
		const url = new URL(withProtocol);
		// new URL() accepts almost any string as a single-label hostname
		// (e.g. a port typo like "9931x"), so require a plausible host:
		// localhost, a dotted name/IP, or a bracketed IPv6 address.
		const host = url.hostname;

		if (host !== 'localhost' && !host.includes('.') && !host.startsWith('[')) {
			return null;
		}

		return url.origin + (url.pathname === '/' ? '' : url.pathname);
	} catch {
		return null;
	}
}

export function isLoopback(base: string): boolean {
	try {
		const { hostname } = new URL(base);

		return hostname === 'localhost' || hostname === '127.0.0.1' || hostname === '[::1]';
	} catch {
		return false;
	}
}

/** ':9931' for a local server, the hostname for a remote one. */
export function llamaServerLabel(base: string): string {
	try {
		const url = new URL(base);

		return isLoopback(base)
			? `:${url.port || (url.protocol === 'https:' ? '443' : '80')}`
			: url.hostname;
	} catch {
		return base;
	}
}

/** Whether a llama-server answers at this base URL. */
export async function probeLlamaServer(base: string): Promise<boolean> {
	try {
		const init: RequestInit & { targetAddressSpace?: 'loopback' } = {
			signal: AbortSignal.timeout(1500)
		};

		// Marks the request as intentionally targeting loopback for Chrome's
		// Local Network Access permission model.
		if (isLoopback(base)) {
			init.targetAddressSpace = 'loopback';
		}

		const res = await fetch(`${base}/v1/models`, init);

		if (!res.ok) {
			return false;
		}

		const body = await res.json();

		return Array.isArray(body?.data);
	} catch {
		return false;
	}
}

import type { FlatTocEntry, TocItem } from './types';
import type { Component } from 'svelte';
import { parse } from 'yaml';

type MdModule = { default: Component };

const pageModules: Record<string, () => Promise<MdModule>> = import.meta.glob<MdModule>(
	'/src/docs/**/*.md'
);
const toctreeFile: Record<string, string> = import.meta.glob('/src/docs/_toctree.yml', {
	eager: true,
	import: 'default',
	query: '?raw'
});

/** '/src/docs/foo/bar.md' → 'foo/bar' */
function normalizeKey(globPath: string): string {
	return globPath.replace(/^\/src\/docs\//, '').replace(/\.md$/, '');
}

const pages = Object.fromEntries(
	Object.entries(pageModules).map(([globPath, loader]) => [normalizeKey(globPath), loader])
);

export const toctree: TocItem[] = parse(Object.values(toctreeFile)[0]) as TocItem[];

/** Depth-first list of linkable toctree entries — powers prev/next and titles. */
export function flattenToc(items: TocItem[]): FlatTocEntry[] {
	return items.flatMap((item) => [
		...(item.local ? [{ local: item.local, title: item.title }] : []),
		...(item.sections ? flattenToc(item.sections) : [])
	]);
}

export function getPageLoader(local: string): (() => Promise<MdModule>) | undefined {
	return pages[local];
}

/** All prerender entries for /docs/[...page]. */
export function listAllEntries(): { page: string }[] {
	return flattenToc(toctree).map(({ local }) => ({ page: local }));
}

// Node of a `_toctree.yml` file (Hugging Face doc-builder compatible shape).
export interface TocItem {
	title: string;
	/** Page id relative to the version root, without extension (link target). */
	local?: string;
	sections?: TocItem[];
	/** Force the default collapse state of this section. */
	isExpanded?: boolean;
	new?: boolean;
}

export interface FlatTocEntry {
	title: string;
	local: string;
}

import type { EntryGenerator, PageLoad } from './$types';
import { error, redirect } from '@sveltejs/kit';
import { flattenToc, getPageLoader, listAllEntries, toctree } from '$lib/docs/content';

export const entries: EntryGenerator = () => listAllEntries();

export const load: PageLoad = async ({ params }) => {
	// The index lives at an explicit /docs/introduction URL so that relative links
	// between markdown pages resolve correctly.
	if (!params.page) {
		redirect(307, '/docs/introduction');
	}

	const local = params.page;
	const loader = getPageLoader(local);

	if (!loader) {
		error(404, `Docs page "${local}" not found`);
	}

	const mod = await loader();
	const flat = flattenToc(toctree);
	const index = flat.findIndex((entry) => entry.local === local);

	return {
		component: mod.default,
		local,
		next: index !== -1 && index < flat.length - 1 ? flat[index + 1] : undefined,
		prev: index > 0 ? flat[index - 1] : undefined,
		title: flat[index]?.title ?? local,
		toctree
	};
};

import { expect, test } from '@playwright/test';

test('home page loads with expected content', async ({ page }) => {
	await page.goto('http://localhost:4173/?os=linux');

	await expect(
		page.getByText('curl -LsSf https://llama.app/install.sh | sh').first()
	).toBeVisible();

	const packageManagersLink = page.getByRole('link', { name: 'Package managers' });

	await expect(packageManagersLink).toBeVisible();
	await expect(packageManagersLink).toHaveAttribute(
		'href',
		'https://github.com/ggml-org/llama.cpp/blob/master/docs/install.md'
	);
});
